-- Apply once through migration tooling. Existing conflicting tables fail safely.
begin;
create schema your_city_private;
revoke all on schema your_city_private from public;
create table public.cities (id uuid primary key default gen_random_uuid(), slug text not null unique, name_kk text not null, name_ru text not null);
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null check (char_length(trim(display_name)) between 2 and 80), city_id uuid references public.cities(id), onboarded boolean not null default false, created_at timestamptz not null default now(), check (not onboarded or city_id is not null));
create table public.communities (id uuid primary key default gen_random_uuid(), city_id uuid not null references public.cities(id), slug text not null, name_kk text not null, name_ru text not null, description_kk text not null default '', description_ru text not null default '', unique(city_id,slug));
create table public.community_memberships (user_id uuid not null references public.profiles(id) on delete cascade, community_id uuid not null references public.communities(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,community_id));
create table public.posts (id uuid primary key default gen_random_uuid(), community_id uuid not null references public.communities(id), author_id uuid not null references public.profiles(id), body text not null check(char_length(trim(body)) between 1 and 5000), hidden boolean not null default false, created_at timestamptz not null default now());
create table public.comments (id uuid primary key default gen_random_uuid(), post_id uuid not null references public.posts(id) on delete cascade, author_id uuid not null references public.profiles(id), body text not null check(char_length(trim(body)) between 1 and 2000), created_at timestamptz not null default now());
create table public.reports (id uuid primary key default gen_random_uuid(), post_id uuid not null references public.posts(id) on delete cascade, reporter_id uuid not null references public.profiles(id), reason text not null check(char_length(trim(reason)) between 5 and 1000), status text not null default 'open' check(status in ('open','resolved','dismissed')), created_at timestamptz not null default now(), unique(post_id,reporter_id));
create table your_city_private.moderators (user_id uuid primary key references auth.users(id) on delete cascade);
alter table your_city_private.moderators enable row level security;
create index communities_city_idx on public.communities(city_id);
create index memberships_community_idx on public.community_memberships(community_id);
create index profiles_city_idx on public.profiles(city_id);
create index posts_feed_idx on public.posts(community_id,created_at desc,id);
create index posts_author_idx on public.posts(author_id);
create index comments_post_idx on public.comments(post_id,created_at);
create index comments_author_idx on public.comments(author_id);
create index reports_queue_idx on public.reports(status,created_at);
create index reports_reporter_idx on public.reports(reporter_id);
create function your_city_private.is_moderator() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from your_city_private.moderators where user_id=(select auth.uid())) $$;
create function your_city_private.is_member(cid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.community_memberships where user_id=(select auth.uid()) and community_id=cid) $$;
create function your_city_private.same_city(cid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles p join public.communities c on c.city_id=p.city_id where p.id=(select auth.uid()) and c.id=cid) $$;
create function your_city_private.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name) values(new.id,case when char_length(trim(coalesce(new.raw_user_meta_data->>'display_name',''))) between 2 and 80 then trim(new.raw_user_meta_data->>'display_name') else 'Тұрғын' end); return new; end $$;
create trigger your_city_user_created after insert on auth.users for each row execute function your_city_private.handle_new_user();
-- Backfill existing accounts without modifying their auth records.
insert into public.profiles(id,display_name) select id,'Тұрғын' from auth.users;
create function your_city_private.guard_profile_city() returns trigger language plpgsql set search_path='' as $$ begin if old.city_id is not null and new.city_id is distinct from old.city_id then raise exception 'City changes require an administrator'; end if; return new; end $$;
create trigger guard_profile_city before update on public.profiles for each row execute function your_city_private.guard_profile_city();
alter table public.cities enable row level security;
alter table public.profiles enable row level security;
alter table public.communities enable row level security;
alter table public.community_memberships enable row level security;
alter table public.posts enable row level security;
alter table public.comments enable row level security;
alter table public.reports enable row level security;
revoke all on public.cities,public.profiles,public.communities,public.community_memberships,public.posts,public.comments,public.reports from anon,authenticated;
grant select on public.cities,public.communities to anon,authenticated;
grant select on public.profiles,public.community_memberships,public.posts,public.comments,public.reports to authenticated;
grant update(display_name) on public.profiles to authenticated;
grant insert(user_id,community_id),delete on public.community_memberships to authenticated;
grant insert(community_id,author_id,body),delete on public.posts to authenticated;
grant insert(post_id,author_id,body),delete on public.comments to authenticated;
grant insert(post_id,reporter_id,reason) on public.reports to authenticated;
grant usage on schema your_city_private to authenticated;
revoke all on all functions in schema your_city_private from public;
grant execute on function your_city_private.is_member(uuid),your_city_private.same_city(uuid),your_city_private.is_moderator() to authenticated;
create policy cities_read on public.cities for select to anon,authenticated using(true);
create policy communities_read on public.communities for select to anon,authenticated using(true);
create policy profiles_read on public.profiles for select to authenticated using(true);
create policy profiles_update on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy memberships_read on public.community_memberships for select to authenticated using(user_id=(select auth.uid()));
create policy memberships_insert on public.community_memberships for insert to authenticated with check(user_id=(select auth.uid()) and your_city_private.same_city(community_id));
create policy memberships_delete on public.community_memberships for delete to authenticated using(user_id=(select auth.uid()));
create policy posts_read on public.posts for select to authenticated using(not hidden or your_city_private.is_moderator());
create policy posts_insert on public.posts for insert to authenticated with check(author_id=(select auth.uid()) and your_city_private.is_member(community_id) and your_city_private.same_city(community_id) and not hidden);
create policy posts_delete on public.posts for delete to authenticated using(author_id=(select auth.uid()) or your_city_private.is_moderator());
create policy comments_read on public.comments for select to authenticated using(exists(select 1 from public.posts p where p.id=post_id));
create policy comments_insert on public.comments for insert to authenticated with check(author_id=(select auth.uid()) and exists(select 1 from public.posts p where p.id=post_id and not p.hidden and your_city_private.is_member(p.community_id)));
create policy comments_delete on public.comments for delete to authenticated using(author_id=(select auth.uid()) or your_city_private.is_moderator());
create policy reports_read on public.reports for select to authenticated using(reporter_id=(select auth.uid()) or your_city_private.is_moderator());
create policy reports_insert on public.reports for insert to authenticated with check(reporter_id=(select auth.uid()) and status='open' and exists(select 1 from public.posts p where p.id=post_id and not p.hidden));
create function public.complete_onboarding(p_name text,p_city uuid,p_communities uuid[]) returns void language plpgsql security definer set search_path='' as $$
declare uid uuid := auth.uid(); begin
 if uid is null then raise exception 'Authentication required'; end if;
 if p_name is null or char_length(trim(p_name)) not between 2 and 80 then raise exception 'Invalid name'; end if;
 if not exists(select 1 from public.cities where id=p_city) then raise exception 'Invalid city'; end if;
 if p_communities is null or cardinality(p_communities)>30 then raise exception 'Invalid communities'; end if;
 if exists(select 1 from unnest(p_communities) cid where cid is null or not exists(select 1 from public.communities where id=cid and city_id=p_city)) then raise exception 'Invalid community city'; end if;
 perform 1 from public.profiles where id=uid for update;
 if not found then raise exception 'Profile missing'; end if;
 update public.profiles set display_name=trim(p_name),city_id=p_city,onboarded=true where id=uid;
 delete from public.community_memberships where user_id=uid;
 insert into public.community_memberships(user_id,community_id) select uid,cid from (select distinct unnest(p_communities) cid) x;
end $$;
revoke all on function public.complete_onboarding(text,uuid,uuid[]) from public;
grant execute on function public.complete_onboarding(text,uuid,uuid[]) to authenticated;
insert into public.cities(slug,name_kk,name_ru) values('shymkent','Шымкент','Шымкент');
insert into public.communities(city_id,slug,name_kk,name_ru) select c.id,v.slug,v.kk,v.ru from public.cities c cross join (values ('drivers','Көлік жүргізушілері','Автолюбители'),('deals','Жеңілдіктер','Скидки и находки'),('news','Қала өмірі','Жизнь города'),('students','Студенттер','Студенты'),('neighborhoods','Көршілер','Соседи'),('events','Іс-шаралар','События'),('market','Қалалық маркет','Городской маркет')) v(slug,kk,ru) where c.slug='shymkent';
commit;
